//! The OpenAPI 3.1 description of the API (generated by scripts/gen-openapi.py).

use axum::http::header;
use axum::response::IntoResponse;

pub const SPEC: &str = include_str!("../../openapi.yaml");

/// `GET /api/openapi.yaml`
pub async fn spec() -> impl IntoResponse {
    ([(header::CONTENT_TYPE, "application/yaml; charset=utf-8")], SPEC)
}

#[cfg(test)]
mod tests {
    /// Every route registered under /api must be documented, with the same methods.
    #[test]
    fn spec_covers_every_route() {
        let routes = include_str!("mod.rs");
        let start = routes.find("let api = Router::new()").expect("api router");
        let api = &routes[start..];
        let api = &api[..api.find(".nest_service(").unwrap_or(api.len())];
        let mut missing = Vec::new();
        let mut checked = 0;
        let mut rest = api;
        while let Some(i) = rest.find(".route(\"") {
            rest = &rest[i + 8..];
            let end = rest.find('"').unwrap();
            let path = &rest[..end];
            // the handler expression up to the end of this .route(...) call
            let call_end = rest.find("\n        .").unwrap_or(rest.len());
            let call = &rest[..call_end];
            checked += 1;
            let key = format!("\n  {path}:\n");
            let Some(at) = super::SPEC.find(&key) else {
                missing.push(path.to_string());
                continue;
            };
            let block = &super::SPEC[at + key.len()..];
            let block = &block[..block.find("\n  /").unwrap_or(block.len())];
            for m in ["get", "post", "put", "patch", "delete"] {
                let used = call.contains(&format!("{m}(")) || call.contains(&format!("routing::{m}("));
                if used && !block.contains(&format!("\n    {m}:")) && !block.starts_with(&format!("    {m}:")) {
                    missing.push(format!("{} {path}", m.to_uppercase()));
                }
            }
        }
        assert!(checked > 100, "only {checked} routes parsed");
        assert!(missing.is_empty(), "undocumented routes (update scripts/gen-openapi.py): {missing:?}");
        assert!(super::SPEC.contains("openapi: 3.1.0"));
    }
}
